const event = $json.body ?? $json;
const required = ['canal', 'destinatario', 'remetente', 'id_externo', 'mensagem'];
for (const field of required) {
  if (typeof event[field] !== 'string' || !event[field].trim()) throw new Error(`Evento inválido: ${field} é obrigatório`);
}
if (event.canal !== 'whatsapp') throw new Error('Evento inválido: somente whatsapp é aceito');
if (event.mensagem.trim().length > 8000) throw new Error('Evento inválido: mensagem excede 8000 caracteres');
const metadata = event.metadados ?? {};
const uuid = /^[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}$/i;
if (!uuid.test(String(metadata.canal_id ?? '')) || !uuid.test(String(metadata.agente_id ?? ''))) throw new Error('Evento inválido: canal_id e agente_id são obrigatórios');
const sql = (value) => `'${String(value ?? '').replace(/'/g, "''")}'`;
const message = event.mensagem.trim();
return { json: {
  canal: 'whatsapp', destinatario: event.destinatario.trim(), remetente: event.remetente.trim(),
  id_externo: event.id_externo.trim(), mensagem: message, metadados: metadata,
  sqlCanal: sql('whatsapp'), sqlDestino: sql(event.destinatario.trim()), sqlRemetente: sql(event.remetente.trim()),
  sqlIdExterno: sql(event.id_externo.trim()), sqlMensagem: sql(message), sqlMetadados: sql(JSON.stringify(metadata)),
  sqlAgenteId: sql(metadata.agente_id)
} };

