with resolucao as (
  select * from atendimento.resolver_inbound({{ $json.sqlCanal }}, {{ $json.sqlDestino }}, {{ $json.sqlRemetente }}, {{ $json.sqlIdExterno }}, {{ $json.sqlMetadados }}::jsonb)
), entrada as (
  select r.*, case when not r.duplicado then atendimento.registrar_mensagem_entrada(r.empresa_id, r.conversa_id, {{ $json.sqlIdExterno }}, {{ $json.sqlMensagem }}) end as mensagem_id
  from resolucao r
)
select e.*, {{ $json.sqlMensagem }} as mensagem,
  (select jsonb_build_object('modelo', a.modelo, 'system_prompt', a.system_prompt, 'temperatura', a.temperatura, 'limite_resposta_tokens', a.limite_resposta_tokens, 'limiar_confianca', a.limiar_confianca, 'versao_conhecimento', a.versao_conhecimento)
   from atendimento.agentes a where a.id={{ $json.sqlAgenteId }}::uuid and a.empresa_id=e.empresa_id and a.ativo) as agente,
  atendimento.obter_memoria_agente(e.empresa_id, e.conversa_id) as memoria,
  atendimento.buscar_conhecimento_rag(e.empresa_id, {{ $json.sqlMensagem }}) as rag_banco,
  ('daza:atendimento:rag:v' || coalesce((select a.versao_conhecimento::text from atendimento.agentes a where a.id={{ $json.sqlAgenteId }}::uuid), '1') || ':empresa:' || e.empresa_id::text || ':q:' || md5({{ $json.sqlMensagem }})) as cache_key
from entrada e;

