const input = $json;
const agent = input.agente;
if (!agent?.modelo || !agent?.system_prompt) throw new Error('Agente ativo não encontrado para o canal');
let rag = ''; let ragCache = false;
try { const parsed = input.rag_cache ? JSON.parse(input.rag_cache) : null; rag = String(parsed?.contexto ?? ''); ragCache = Boolean(rag); } catch {}
if (!rag) {
  const databaseRag = input.rag_banco;
  rag = typeof databaseRag === 'string' ? databaseRag : String(databaseRag?.contexto ?? databaseRag ?? '');
}
const memory = Array.isArray(input.memoria) ? input.memoria : (Array.isArray(input.memoria?.mensagens) ? input.memoria.mensagens : []);
const history = memory.slice(-12).map((item) => ({ role: item.role === 'assistant' || item.direcao === 'saida' ? 'assistant' : 'user', content: String(item.content ?? item.conteudo ?? '') })).filter((item) => item.content);
const system = `${agent.system_prompt}

REGRAS INEGOCIÁVEIS:
- Responda em português do Brasil.
- Use somente o contexto abaixo; não invente preços, políticas, prazos ou disponibilidade.
- Se não houver contexto suficiente, se houver risco, alteração sensível ou pedido humano, escolha escalar.
- Retorne somente JSON válido: {"acao":"responder"|"escalar","resposta":"texto","motivo_escalonamento":"texto opcional"}.

CONTEXTO RAG:
${rag || '(nenhum contexto confiável encontrado)'}`;
return { json: { ...input, rag, rag_cache: ragCache, body: { model: agent.modelo, temperature: Number(agent.temperatura ?? 0.2), max_tokens: Number(agent.limite_resposta_tokens ?? 450), messages: [{ role: 'system', content: system }, ...history, { role: 'user', content: input.mensagem }] } } };

const context = $('06 — Preparar prompt e cache').first().json;
const fallback = (reason) => ({ empresa_id: context.empresa_id, conversa_id: context.conversa_id, acao: 'escalar', resposta: 'Entendi. Vou encaminhar seu atendimento para uma pessoa da equipe.', motivo_escalonamento: reason, modelo: context.body.model, rag_cache: context.rag_cache });
try {
  const raw = String($json.choices?.[0]?.message?.content ?? '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  const parsed = JSON.parse(raw);
  if (!['responder', 'escalar'].includes(parsed.acao) || typeof parsed.resposta !== 'string' || !parsed.resposta.trim()) return { json: fallback('Resposta estruturada inválida do modelo') };
  return { json: { empresa_id: context.empresa_id, conversa_id: context.conversa_id, acao: parsed.acao, resposta: parsed.resposta.trim().slice(0, 8000), motivo_escalonamento: parsed.acao === 'escalar' ? String(parsed.motivo_escalonamento || 'Solicitação exige atendimento humano').slice(0, 2000) : undefined, modelo: context.body.model, rag_cache: context.rag_cache } };
} catch { return { json: fallback('Falha ao interpretar a resposta do modelo') }; }
